const discoveryRender=render;
render=function(){discoveryRender();let panel=$('kingdomGoals');if(!panel){panel=document.createElement('section');panel.id='kingdomGoals';panel.className='goals-panel';$('stats').after(panel);}const wasOpen=panel.querySelector('details')?.open,c=ctry(),goals=Objectives.progress(state,c);panel.innerHTML=`<details ${wasOpen?'open':''}><summary>🏆 Our kingdom goals · ${Object.keys(c.badges).length} / 4 achieved · Focus: ${esc(Objectives.names[c.ambition])}</summary><p>Every council role helps the same kingdom. Meet all checks on a card for <b>3 results in a row</b> to earn it. Choose either route where you see OR. Other kingdoms can succeed too; earning a badge does not end the game.</p>${field('Our current focus','ambition',Object.entries(Objectives.names),c.ambition,'This highlights a shared goal. You can still earn every achievement.')}<div class="goal-grid">${Object.entries(goals).map(([key,p])=>`<article class="goal-card ${key===c.ambition?'chosen':''}"><h3>${Objectives.names[key]} ${c.badges[key]?'✓':''}</h3><p>${p.description}</p>${p.metrics.map(m=>`<label>${m.met?'✓':'○'} ${m.label}: ${m.value} / ${m.target}<progress value="${Math.max(0,m.value)}" max="${m.target}"></progress></label>`).join('')}<p>${p.route.met?'✓':'○'} <b>Either route:</b> ${p.routeText.replace(' · ',' OR ')}</p><p>${p.extra?'✓':'○'} ${p.extraText}</p><strong>${c.badges[key]?'Earned on turn '+c.badges[key]:c.goalStreak[key]+' / 3 successful turns'}</strong></article>`).join('')}</div><p class="role-intro">Economy supplies the resources; research improves production and learning; military protects supply and negotiates agreements. Completed badges remain in your kingdom record.</p></details>`;$('ambition').disabled=state.phase!=='implement';$('ambition').onchange=e=>action(()=>c.ambition=e.target.value);};
render();
